test('starts at initial position and not dragging', () => {
  const { result } = renderHook(() => useDragState({ x: 10, y: 20 }));
  expect(result.current.position).toEqual({ x: 10, y: 20 });
  expect(result.current.isDragging).toBe(false);
});

test('onMouseDown is a function', () => {
  const { result } = renderHook(() => useDragState({ x: 0, y: 0 }));
  expect(typeof result.current.onMouseDown).toBe('function');
});

test('isDragging becomes true after mousedown', () => {
  const { result } = renderHook(() => useDragState({ x: 0, y: 0 }));
  act(() => result.current.onMouseDown({ clientX: 0, clientY: 0 } as MouseEvent));
  expect(result.current.isDragging).toBe(true);
});

test('position updates on mousemove while dragging', () => {
  const { result } = renderHook(() => useDragState({ x: 0, y: 0 }));
  act(() => result.current.onMouseDown({ clientX: 5, clientY: 5 } as MouseEvent));
  act(() => { document.dispatchEvent(new MouseEvent('mousemove', { clientX: 15, clientY: 25 })); });
  expect(result.current.position).toEqual({ x: 10, y: 20 });
});

// __hidden__
test('isDragging becomes false on mouseup', () => {
  const { result } = renderHook(() => useDragState({ x: 0, y: 0 }));
  act(() => result.current.onMouseDown({ clientX: 0, clientY: 0 } as MouseEvent));
  act(() => { document.dispatchEvent(new MouseEvent('mouseup')); });
  expect(result.current.isDragging).toBe(false);
});

solution:
import { useState, useEffect, useCallback, useRef } from 'react';

type Point = { x: number; y: number };

export function useDragState(initial: Point) {
  const [position, setPosition] = useState<Point>(initial);
  const [isDragging, setIsDragging] = useState(false);
  const startRef = useRef<Point>({ x: 0, y: 0 });
  const originRef = useRef<Point>(initial);

  const onMouseDown = useCallback((e: MouseEvent) => {
    startRef.current = { x: e.clientX, y: e.clientY };
    originRef.current = position;
    setIsDragging(true);
  }, [position]);

  useEffect(() => {
    if (!isDragging) return;

    const onMouseMove = (e: MouseEvent) => {
      setPosition({
        x: originRef.current.x + e.clientX - startRef.current.x,
        y: originRef.current.y + e.clientY - startRef.current.y,
      });
    };

    const onMouseUp = () => setIsDragging(false);

    document.addEventListener('mousemove', onMouseMove);
    document.addEventListener('mouseup', onMouseUp);
    return () => {
      document.removeEventListener('mousemove', onMouseMove);
      document.removeEventListener('mouseup', onMouseUp);
    };
  }, [isDragging]);

  return { position, onMouseDown, isDragging };
}
